int foundry_terrain_v1_shape_find(const char *name) {
  static const char *const names[] = {"canyon_pass", "coast_town", "crossroads", "glade", "highland", "marsh_basin", "river_valley"};
  for (int i = 0; name && i < 7; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_terrain_v1_flat_find(const char *name) {
  static const char *const names[] = {"hamlet", "none", "town", "village"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

